{"policy":"permit (
    principal is User,
    action == Action::"approveAward",
    resource is Award
)
when {
    (principal.roles.contains(Role::"ProgramOfficer") ||
     principal.roles.contains(Role::"GrantsOfficer")) &&
    principal.approvalAuthority >= resource.application.fundingTier
};

forbid (
    principal is User,
    action == Action::"approveAward",
    resource is Award
)
when {
    (principal.roles.contains(Role::"ProgramOfficer") ||
     principal.roles.contains(Role::"GrantsOfficer")) &&
    principal.approvalAuthority < resource.application.fundingTier
};

permit (
    principal is User,
    action == Action::"obligateFunds",
    resource is Award
)
when {
    principal.roles.contains(Role::"ProgramOfficer")
};

forbid (
    principal is User,
    action == Action::"obligateFunds",
    resource is Award
)
when {
    !principal.roles.contains(Role::"GrantsOfficer")
};

forbid (
    principal is User,
    action == Action::"obligateFunds",
    resource is Award
)
when {
    principal.roles.contains(Role::"GrantsOfficer") &&
    resource has approvedBy &&
    resource.approvedBy == principal
};"}
